import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty_remaining]
    seq_counter = [0]

    def next_seq():
        seq_counter[0] += 1
        return seq_counter[0]

    def is_active(oid):
        return oid in book and book[oid][2] > 0

    def clean_buy_heap():
        while buy_heap and not is_active(buy_heap[0][2]):
            heapq.heappop(buy_heap)

    def clean_sell_heap():
        while sell_heap and not is_active(sell_heap[0][2]):
            heapq.heappop(sell_heap)

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                book[oid][2] = 0
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            clean_sell_heap()
            while remaining > 0 and sell_heap:
                top_price, top_seq, top_id = sell_heap[0]
                if not is_active(top_id):
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and top_price > price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    heapq.heappop(sell_heap)
                clean_sell_heap()
            if typ == 'limit' and remaining > 0:
                s = next_seq()
                book[oid] = ['buy', price, remaining]
                heapq.heappush(buy_heap, (-price, s, oid))
        else:  # sell
            clean_buy_heap()
            while remaining > 0 and buy_heap:
                neg_price, top_seq, top_id = buy_heap[0]
                top_price = -neg_price
                if not is_active(top_id):
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and top_price < price:
                    break
                resting = book[top_id]
                trade_qty = min(remaining, resting[2])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                resting[2] -= trade_qty
                if resting[2] == 0:
                    heapq.heappop(buy_heap)
                clean_buy_heap()
            if typ == 'limit' and remaining > 0:
                s = next_seq()
                book[oid] = ['sell', price, remaining]
                heapq.heappush(sell_heap, (price, s, oid))

    return trades

